/* ---------- word list for Scrabble (public-domain Webster word list, 2 to 9 letters), unpacked on first use ---------- */
const Dict = (() => {
  const B64 = '';
  let set = null, list = [], prom = null;
  const load = () => prom || (prom = (async () => {
    try {
      const bin = atob(B64), u = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i);
      const txt = await new Response(new Blob([u]).stream().pipeThrough(new DecompressionStream('gzip'))).text();
      list = txt.split(' '); set = new Set(list);
    } catch (e) { set = null; list = []; }
  })());
  const base = w => set.has(w);
  // a word is fine if it is listed, or is a plain plural or past tense of a listed word
  const has = w => {
    if (!set) return /^[a-z]{2,15}$/.test(w);
    if (base(w)) return true; const n = w.length;
    if (n > 3 && w.endsWith('s') && base(w.slice(0, -1))) return true;
    if (n > 4 && w.endsWith('es') && base(w.slice(0, -2))) return true;
    if (n > 4 && w.endsWith('ies') && base(w.slice(0, -3) + 'y')) return true;
    if (n > 4 && w.endsWith('ed') && (base(w.slice(0, -2)) || base(w.slice(0, -1)))) return true;
    if (n > 5 && w.endsWith('ing') && (base(w.slice(0, -3)) || base(w.slice(0, -3) + 'e'))) return true;
    return false;
  };
  return { load, has, get list() { return list; }, get ok() { return !!set; } };
})();
